/** One damage the customer reports: which kind of item was damaged, and by how much. */
public record Damage(String itemType, BigDecimal amount) {
}
/**
 * An item a policy covers, as the office records it.
 *
 * The office reads the recorded facts to classify the item's risk, so the
 * classifications live here with the facts they read, while what each risk
 * costs is the premium rules' business in {@link PremiumPolicy}. The
 * enchantment level carries more than one such classification: the premium
 * rules surcharge a high enchantment from level 5 up, and the claim rules have
 * their own, higher threshold, so each threshold is named for the rule it
 * serves rather than sharing one vague "enchanted" predicate.
 */
public record InsuredItem(String type, boolean cursed, int enchantment) {

    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
    private static final int UNRULY_ENCHANTMENT_LEVEL = 8;

    /**
     * The office counts an item as highly enchanted, and so as carrying a risk
     * worth a surcharge, from enchantment level 5 up.
     */
    public boolean isHighlyEnchanted() {
        return enchantment >= HIGH_ENCHANTMENT_LEVEL;
    }

    /**
     * From enchantment level 8 up the office considers an item too unruly for
     * its damage to be reimbursed in full. What such a damage earns instead is
     * the claim rules' clause to state, in {@link ClaimPolicy}.
     */
    public boolean isTooUnrulyToReimburseInFull() {
        return enchantment >= UNRULY_ENCHANTMENT_LEVEL;
    }
}
import java.math.BigDecimal;
import java.util.List;

/**
 * A policy the office has written: the {@link Coverage} it was written over and
 * the {@link PayoutCap} it was written under.
 *
 * Settling an incident against the policy is this policy's decision, not the
 * protocol's, and all it decides is how the three parties to a settlement meet:
 * the coverage says which covered item a reported damage is settled on, the
 * {@link ClaimPolicy} says what that one damage earns, and the cap says how much
 * of it is actually paid. So the deductible is borne once per damage reported
 * and the cap is consumed in the order the damages are reported.
 */
public class Policy {

    private final Coverage coverage;
    private final PayoutCap payoutCap;

    /**
     * The office writes a policy over the items a customer brings: what it
     * insures them for is the {@link PriceList}'s to state, and the cap that
     * insurance sum earns is the cap's own rule. Premium modifiers are no part
     * of it, which is why the policy is written from the covered items and never
     * from the premium quoted for them.
     */
    public static Policy covering(List<InsuredItem> insuredItems, PriceList priceList) {
        return new Policy(Coverage.of(insuredItems),
                PayoutCap.forInsuranceSum(priceList.insuranceSum(insuredItems)));
    }

    private Policy(Coverage coverage, PayoutCap payoutCap) {
        this.coverage = coverage;
        this.payoutCap = payoutCap;
    }

    /**
     * What the office pays for one reported incident: every damage reimbursed on
     * its own terms, the total limited to the cap the policy has left.
     */
    public BigDecimal settle(List<Damage> damages, ClaimPolicy claimPolicy) {
        BigDecimal paid = BigDecimal.ZERO;
        for (Damage damage : damages) {
            paid = paid.add(payoutCap.pay(claimPolicy.reimbursementFor(
                    damage.amount(), coverage.itemDamagedBy(damage))));
        }
        return paid;
    }

    public BigDecimal remainingCap() {
        return payoutCap.remaining();
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;
import java.io.UncheckedIOException;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

/**
 * Translates the JSON scenario protocol into MHPCO operations and back. The
 * protocol field names are binding; what the office does with a step, and what
 * it carries from one step to the next, is the {@link ClaimOffice}'s business.
 */
public class ClaimOfficeCli {

    private static final ObjectMapper JSON = new ObjectMapper();

    public void run(InputStream scenario, PrintStream results) {
        try {
            JsonNode input = JSON.readTree(scenario);
            ClaimOffice office =
                    new ClaimOffice(input.get("customer").get("yearsWithMHPCO").asInt());
            ObjectNode output = JSON.createObjectNode();
            ArrayNode resultsNode = output.putArray("results");
            JsonNode steps = input.get("steps");
            for (int stepIndex = 0; stepIndex < steps.size(); stepIndex++) {
                JsonNode step = steps.get(stepIndex);
                if ("claim".equals(step.get("op").asText())) {
                    writeSettlement(office.settleClaim(step.get("policy").asInt(), damages(step)),
                            resultsNode.addObject());
                    continue;
                }
                resultsNode.addObject().put("premium",
                        office.quote(stepIndex, insuredItems(step)));
            }
            results.print(JSON.writeValueAsString(output));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static void writeSettlement(ClaimOffice.Settlement settlement, ObjectNode result) {
        result.put("payout", settlement.payout().intValueExact());
        result.put("remainingCap", settlement.remainingCap().intValueExact());
    }

    private static List<Damage> damages(JsonNode claimStep) {
        List<Damage> damages = new ArrayList<>();
        for (JsonNode damage : claimStep.get("incident").get("damages")) {
            damages.add(new Damage(damage.get("itemType").asText(),
                    new BigDecimal(damage.get("amount").asText())));
        }
        return damages;
    }

    private static List<InsuredItem> insuredItems(JsonNode quoteStep) {
        List<InsuredItem> items = new ArrayList<>();
        for (JsonNode item : quoteStep.get("items")) {
            items.add(new InsuredItem(item.get("type").asText(),
                    item.path("cursed").asBoolean(false),
                    item.path("enchantment").asInt(0)));
        }
